# test simple local aligner against planning target sequences
import requests,zipfile,io,json

def fetch_gene(gid, accession_filter=None):
    params={'include_annotation_type':['FASTA_RNA'],'aux_report':['PRODUCT_REPORT']}
    if accession_filter: params['accession_filter']=accession_filter
    r=requests.get(f'https://api.ncbi.nlm.nih.gov/datasets/v2/gene/id/{gid}/download',params=params,timeout=120)
    z=zipfile.ZipFile(io.BytesIO(r.content))
    rep=[json.loads(l) for l in z.read('ncbi_dataset/data/product_report.jsonl').decode().splitlines()][0]
    seqs={}; cur=None; seq=[]
    for line in z.read('ncbi_dataset/data/rna.fna').decode().splitlines():
        if line.startswith('>'):
            if cur: seqs[cur]=''.join(seq)
            cur=line[1:].split()[0]; seq=[]
        else: seq.append(line.strip())
    if cur: seqs[cur]=''.join(seq)
    return rep,seqs

def local_align(a,b,match=2,mismatch=-1,gap=-1):
    n=len(a); m=len(b)
    H=[[0]*(m+1) for _ in range(n+1)]
    maxscore=0; maxi=maxj=0
    for i in range(1,n+1):
        for j in range(1,m+1):
            diag=H[i-1][j-1]+(match if a[i-1]==b[j-1] else mismatch)
            up=H[i-1][j]+gap
            left=H[i][j-1]+gap
            H[i][j]=max(0,diag,up,left)
            if H[i][j]>maxscore:
                maxscore=H[i][j]; maxi=i; maxj=j
    # traceback to start
    i=maxi; j=maxj; aaln=[]; baln=[]
    while i>0 and j>0 and H[i][j]>0:
        if H[i][j]==H[i-1][j-1]+(match if a[i-1]==b[j-1] else mismatch):
            aaln.append(a[i-1]); baln.append(b[j-1]); i-=1; j-=1
        elif H[i][j]==H[i-1][j]+gap:
            aaln.append(a[i-1]); baln.append('-'); i-=1
        else:
            aaln.append('-'); baln.append(b[j-1]); j-=1
    aaln=''.join(reversed(aaln)); baln=''.join(reversed(baln))
    tstart=j; tend=maxj
    seg=b[tstart:tend]
    return maxscore,i,j,aaln,baln,seg

def lev(a,b):
    dp=list(range(len(b)+1))
    for i,ca in enumerate(a,1):
        prev=dp[0]; dp[0]=i
        for j,cb in enumerate(b,1):
            old=dp[j]; dp[j]=min(prev+(ca"'!=cb),dp[j]+1,dp[j-1]+1); prev=old
    return dp[-1]

rep,seqs=fetch_gene('"'6469',['NM_000193.4']); human_rna=seqs['NM_000193.4']; human=human_rna[341:641]
for gid in ['743371','716553','100995872','100481788','111176269']:
    rep,seqs=fetch_gene(gid)
    trs=[t for t in rep['transcripts'] if 'cds' in t and t.get('type','').startswith('PROTEIN_CODING')]
    tr=max(trs,key=lambda t:int(t['protein']['length'])); target=seqs[tr['accessionVersion']]
    score,i,j,aaln,baln,seg=local_align(human,target)
    print(gid,tr['accessionVersion'],'score',score,'start',j,'end',j+len(seg),'len',len(seg),'dist',lev(human,seg),seg[:80])
